"""Self-contained reply gallery and motion studies; image files are inlined by T3."""
from pathlib import Path
import json,sys
ROOT=Path(__file__).resolve().parents[1]
folder=sys.argv[1]if len(sys.argv)>1 else'a2-r2'
D=json.loads((ROOT/'assets/a2/concept-data.json').read_text())
ids=list(range(0,601,4));ids=sorted(set(ids+[442]))
samples=[[D['trace'][i]['d'],D['trace'][i]['nor']['speed'],D['trace'][i]['ver']['speed'],D['trace'][i]['nor']['throttle'],D['trace'][i]['ver']['throttle'],D['trace'][i]['nor']['brake'],D['trace'][i]['ver']['brake'],D['trace'][i]['delta']]for i in ids]
# JSON stores only the numbers used by the motion excerpt, not complete endpoint objects.
data='window.STUDY_SAMPLES='+json.dumps(samples,separators=(',',':'))+';window.STUDY_GAPS='+json.dumps([[d['code'],d['gap']]for d in D['drivers'][1:]],separators=(',',':'))+';'
P=[('01-race-overview','Race overview','The full field stays central. Camera controls, race order and three global destinations.','Spectate first, inspect when you want to.'),('02-live-timing','Live timing dashboard','All22 cars in one timing tower: gaps or intervals, last completed laps, compounds and tyre ages.','Dense where comparison is the job.'),('03-driver-follow','Driver follow','A close camera inside the same miniature, with readable speed, throttle, brake state and gear.','Reconstructed3D, not licensed onboard video.'),('04-telemetry-lab','Telemetry lab','Speed, throttle, binary brake and lap delta share one distance-aligned cursor. Compare completed laps without confusing their delta with the current race gap.','Norris−Verstappen: negative means Norris ahead.'),('05-strategy-workbench','Strategy workbench','Change an assumed pit loss and inspect a fixed-gap rejoin scenario, alongside actual-style stint history.','An explicit what-if, not an invented prediction.'),('06-feed-interrupted','Feed interruption','Freeze the last-known model, state data age and expose recovery. Never continue a false live animation.','Honest failure states are part of the product.'),('07-light-studio','Light studio','The same olive miniature and instrument hierarchy, designed against a lighter studio ground.','A second colour mode, not a different art direction.'),('08-camera-storyboard','Camera choreography','Overview → select Norris → follow. A30-frame camera journey through the real model.','480ms in;420ms out; reduced-motion alternative.'),('09-vantage-icon','The app icon','An elevated circuit crossover, with one car-sized orange mark.','Original concept; brand name remains provisional.')]
css='''*{box-sizing:border-box}html,body{margin:0;background:transparent;color:var(--foreground);font-family:var(--font-sans,-apple-system,sans-serif)}main{width:100%;padding:0}p{margin:0}button{font:inherit;color:inherit;cursor:pointer}button:focus-visible,input:focus-visible{outline:2px solid var(--ring);outline-offset:3px}.intro{font-size:14px;line-height:1.6;color:var(--muted-foreground);margin-bottom:16px}.modebar{display:flex;gap:8px;margin-bottom:22px}.modebar button,.back-all,.reduce-motion{min-height:44px;padding:9px 14px;background:transparent;border:1px solid var(--border);border-radius:var(--radius);font-size:13px}.modebar [aria-pressed=true]{background:var(--secondary);border-color:var(--foreground)}.screen-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px 14px}.screen-grid figure{margin:0;min-width:0}.screen-grid .photo{display:block;width:100%;padding:0;border:0;background:none;border-radius:13%;line-height:0}.screen-grid img{display:block;width:100%;height:auto;border-radius:13%}.screen-grid h2{font-size:14px;line-height:1.35;letter-spacing:-.2px;margin:12px 0 0}.focus-view{display:none;grid-template-columns:minmax(0,370px) minmax(0,1fr);gap:26px;align-items:start}.focus-view img{display:block;width:100%;height:auto;max-width:402px;margin:auto;border-radius:13%}.focus-copy{padding-top:14px}.focus-copy small{color:var(--muted-foreground);font-size:12px}.focus-copy h2{font-size:28px;letter-spacing:-.8px;line-height:1.15;margin:12px 0 18px}.focus-copy p{font-size:14px;line-height:1.7;color:var(--muted-foreground);margin-bottom:18px}.back-all{margin-top:6px}.motion-studies{display:none;--mink:#f2f4f0;--m2:#a8b8bc;--maccent:#b9d4f5;--mground:#111a1d;color:var(--foreground)}.motion-top{display:flex;align-items:center;justify-content:space-between;gap:14px;margin-bottom:18px}.motion-top p{font-size:13px;line-height:1.6;color:var(--muted-foreground)}.reduce-motion{flex:none;font-size:12px}.reduce-motion[aria-pressed=true]{background:var(--secondary)}.camera-study{background:#111a1d;color:#f2f4f0;padding:20px;border-radius:var(--radius);display:grid;grid-template-columns:minmax(0,400px) minmax(0,1fr);gap:24px;align-items:center}.camera-film{width:100%;min-width:0}.camera-film canvas{width:100%;height:auto;aspect-ratio:4/3;display:block;border-radius:12px}.camera-copy h2,.linked-study h2{font-size:17px;line-height:1.3;letter-spacing:-.3px;margin:0 0 10px}.camera-copy p{font-size:13px;line-height:1.6;color:#a8b8bc;margin-bottom:16px}.camera-selector{display:flex;position:relative;isolation:isolate;background:#1e2a2f;border:1px solid #344247;border-radius:26px;padding:4px}.camera-selector .camera-knob{position:absolute;left:4px;top:4px;bottom:4px;width:calc((100% - 8px)/2);background:#b9d4f5;border-radius:22px;z-index:-1;transition:transform 250ms linear(0,.2,.6,.84,.94,.99,1)}.camera-selector button{min-width:0;flex:1;min-height:44px;border:0;background:none;color:#a8b8bc;font-size:13px;transition:color 120ms}.camera-selector [aria-pressed=true]{color:#142735;font-weight:600}.camera-replay{margin-top:8px;border:0;background:none;min-height:44px;padding:0;color:#b9d4f5;font-size:13px}.camera-status{font-size:12px;line-height:1.55;color:#a8b8bc;min-height:38px;margin-top:6px}.motion-studies[data-reduced=true] .camera-knob{transition:none}.camera-sprite{display:none}.linked-study{padding-top:28px;margin-top:24px;border-top:1px solid var(--border)}.study-heading{display:flex;align-items:center;justify-content:space-between;gap:16px}.study-heading>p{font-size:12px;color:var(--muted-foreground)}.legend-values{display:flex;gap:20px;align-items:baseline;margin:15px 0 5px;font-size:13px}.legend-values .n,.legend-values .v{color:var(--foreground)}.legend-values .n:before{content:'';display:inline-block;width:15px;height:2px;background:#C5833F;margin-right:6px;vertical-align:4px}.legend-values .v:before{content:'';display:inline-block;width:15px;border-top:2px dashed #577FAB;margin-right:6px;vertical-align:4px}.legend-values b{font-family:var(--font-mono,monospace);font-size:22px;font-weight:500;margin-left:7px}.legend-values .study-distance{margin-left:auto;color:var(--muted-foreground);font-family:var(--font-mono,monospace);font-size:13px}.study-plot{width:100%;height:145px;display:block;touch-action:pan-y;overflow:visible}.study-plot .grid{stroke:var(--border);stroke-width:.7}.study-plot text{font-size:12px;fill:var(--muted-foreground)}.study-plot .trace{fill:none;stroke:#C5833F;stroke-width:1.7;stroke-linejoin:round;stroke-linecap:round}.study-plot .trace.v{stroke:#577FAB;stroke-dasharray:4 3}.study-cursor{stroke:var(--foreground);stroke-width:.8}.motion-studies input[type=range]{appearance:none;background:transparent;width:100%;height:44px;margin:0;cursor:ew-resize}.motion-studies input[type=range]::-webkit-slider-runnable-track{height:2px;background:var(--border)}.motion-studies input[type=range]::-webkit-slider-thumb{appearance:none;width:18px;height:18px;margin-top:-8px;background:var(--foreground);border:3px solid var(--background);border-radius:50%;box-shadow:0 0 0 1px var(--muted-foreground)}.linked-readouts{display:flex;justify-content:space-between;gap:16px;font-size:13px;color:var(--muted-foreground)}.linked-readouts b{font-family:var(--font-mono,monospace);font-weight:500;color:var(--foreground);margin-left:7px}.throttle-track{margin-top:8px;height:3px;background:var(--border);width:110px;overflow:hidden}.throttle-fill{height:100%;background:var(--foreground);transform-origin:left;transform:scaleX(.99)}.micro-row{display:grid;grid-template-columns:1fr 1.4fr;gap:26px;margin-top:30px;border-top:1px solid var(--border);padding-top:22px}.micro-row h3{font-size:15px;line-height:1.5;margin:0 0 11px}.tick-figure{font:500 34px/1.2 var(--font-mono,monospace);letter-spacing:-1px;display:flex;gap:4px;align-items:baseline}.tick-figure small{font-size:13px;letter-spacing:0;color:var(--muted-foreground);margin-left:5px}.tick-context,.study-neighbours{font-size:12px;line-height:1.65;color:var(--muted-foreground);margin-top:9px;min-height:36px}.timing-tick{padding:8px 13px;min-height:44px;margin-top:10px;border:1px solid var(--border);border-radius:var(--radius);background:none;font-size:13px}.pit-result{display:flex;justify-content:space-between;align-items:baseline;gap:10px}.study-rejoin{font:500 34px/1.2 var(--font-mono,monospace);letter-spacing:-1px}.pit-result label{font-size:13px;color:var(--muted-foreground)}.study-loss{font-family:var(--font-mono,monospace);color:var(--foreground);margin-left:6px}.scope{font-size:12px;line-height:1.7;color:var(--muted-foreground);border-top:1px solid var(--border);margin-top:25px;padding-top:16px}.scope b{color:var(--foreground);font-weight:550}.scope p+p{margin-top:7px}details{font-size:12px;line-height:1.75;color:var(--muted-foreground);margin-top:10px}summary{min-height:44px;display:flex;align-items:center;cursor:pointer;gap:8px}summary:before{content:'+';font-size:18px}details[open] summary:before{content:'−'}details p{margin:0 0 10px}code{font-family:var(--font-mono,monospace);font-size:11px;overflow-wrap:anywhere}main[data-mode=motion] .screen-grid,main[data-mode=motion] .focus-view{display:none}main[data-mode=motion] .motion-studies{display:block}main[data-mode=focus] .screen-grid{display:none}main[data-mode=focus] .focus-view{display:grid}
@media(max-width:560px){.screen-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:22px 12px}.screen-grid h2{font-size:12px}.focus-view{grid-template-columns:1fr;gap:20px}.focus-view img{max-width:370px}.focus-copy{padding-top:0}.focus-copy h2{font-size:26px;margin:9px 0 13px}.camera-study{grid-template-columns:1fr;padding:16px;gap:15px}.camera-copy h2{margin-bottom:8px}.camera-copy p{margin-bottom:12px}.camera-status{min-height:0}.motion-top{align-items:flex-start}.motion-top p{font-size:12px}.reduce-motion{font-size:11px;padding:9px}.study-heading{display:block}.study-heading>p{margin-top:7px}.linked-readouts{font-size:12px;gap:8px}.legend-values{gap:14px}.legend-values b{font-size:20px}.micro-row{grid-template-columns:1fr;gap:22px}.micro-row>div+div{padding-top:20px;border-top:1px solid var(--border)}.tick-context,.study-neighbours{min-height:0}.intro{font-size:13px}}
@media(prefers-reduced-motion:reduce){.camera-knob{transition:none!important}}'''
figures=''
for i,(slug,name,description,note)in enumerate(P):
 path=str(ROOT/'shots'/folder/(slug+'.png'))
 figures+=f'<figure><button class="photo" data-screen="{i}" aria-label="Enlarge {name}"><img src="{path}" alt="{name} visual concept"></button><figcaption><h2>{i+1:02d} / {name}</h2></figcaption></figure>'
def points(who):
 col=1 if who=='nor' else 2
 return ' '.join(f'{28+s[0]/5807*324:.1f},{8+(360-s[col])/300*119:.1f}'for s in samples)
plot=f'<svg class="study-plot" viewBox="0 0 362 145" aria-label="Distance-aligned speed comparison">'+''.join(f'<line class="grid" x1="28" x2="352" y1="{8+(360-n)/300*119:.1f}" y2="{8+(360-n)/300*119:.1f}"/><text x="21" y="{12+(360-n)/300*119:.1f}" text-anchor="end">{n}</text>'for n in [100,200,300])+f'<polyline class="trace" points="{points("nor")}"/><polyline class="trace v" points="{points("ver")}"/><line class="study-cursor" x1="267" x2="267" y1="0" y2="130"/><text x="28" y="144">0 km</text><text x="352" y="144" text-anchor="end">5.807 km</text></svg>'
motion=f'''<section class="motion-studies" data-reduced="false"><div class="motion-top"><p>Four working motion studies. Nothing auto-plays.<br>All telemetry and timing are simulated.</p><button class="reduce-motion" aria-pressed="false">Reduced motion</button></div><div class="camera-study"><div class="camera-film"><canvas width="400" height="300" role="img" aria-label="3D camera journey from the full circuit to Norris"></canvas><img class="camera-sprite" src="{ROOT}/assets/a2/camera-strip.webp" alt=""></div><div class="camera-copy"><h2>01 / Dive into the miniature</h2><p>The camera moves through actual3D geometry. Norris stays anchored; the cars are frozen at one simulated moment.</p><div class="camera-selector"><i class="camera-knob"></i><button data-motion-camera="0" aria-pressed="true">Circuit</button><button data-motion-camera="1" aria-pressed="false">Follow NOR</button></div><button class="camera-replay">Replay the dive</button><div class="camera-status" aria-live="polite">Overview · all22 cars in frame</div></div></div><section class="linked-study"><div class="study-heading"><h2>02 / One cursor, linked telemetry</h2><p>Completed lap30 · distance aligned</p></div><div class="legend-values"><span class="n">NOR<b class="study-speed-nor">263</b></span><span class="v">VER<b class="study-speed-ver">265</b></span><span class="study-distance">4.278 km</span></div>{plot}<input class="study-scrubber" type="range" min="0" max="1000" step="1" value="737" aria-label="Inspect telemetry distance"><div class="linked-readouts"><div>Throttle<b class="study-throttle">99%</b><div class="throttle-track"><div class="throttle-fill"></div></div></div><div>Brake<b class="study-brake">Off</b></div><div>Delta<b class="study-delta">−0.307s</b></div></div></section><div class="micro-row"><div><h3>03 / A timing tick, not a page animation</h3><div class="tick-figure">+<span class="tick-number">1.842</span><small>s</small></div><p class="tick-context">Verstappen to leader · simulated</p><button class="timing-tick">Simulate update</button></div><div><h3>04 / Adjust the pit assumption</h3><div class="pit-result"><strong class="study-rejoin">P7</strong><label>Pit loss, assumed<span class="study-loss">22.4s</span></label></div><input class="study-pit" type="range" min="14" max="30" step=".1" value="22.4" aria-label="Assumed pit loss"><p class="study-neighbours">Behind ANT by4.171s · ahead of ALO by2.634s</p></div></div></section>'''
initial=P[0]
body=f'''<main data-mode="screens"><p class="intro">A, expanded: the whole race first, a deeper instrument layer when you want it. Tap any screen to inspect.</p><nav class="modebar" aria-label="Concept presentation"><button data-mode="screens" aria-pressed="true">Screen set · 8 + icon</button><button data-mode="motion" aria-pressed="false">Try the motion studies</button></nav><div class="screen-grid">{figures}</div><div class="focus-view"><img id="focus-image" src="{ROOT}/shots/{folder}/01-race-overview.png" alt="Selected concept"><section class="focus-copy"><small id="focus-index">Screen01</small><h2 id="focus-title">Race overview</h2><p id="focus-description">{initial[2]}</p><p id="focus-note">{initial[3]}</p><button class="back-all">All screens</button></section></div>{motion}<div class="scope"><p><b>Concepts, not a connected live product.</b> Original3D miniature, simulated race data, rendered camera travel. Native haptics, live positioning and commercial data rights remain unverified.</p><p>Race / Timing / Lab keeps casual viewing simple. Enthusiast features stay inside Lab. Brake is on/off, lap delta is derived, and pit loss is an explicit assumption.</p></div><details><summary>Design checks, sources &amp; files</summary><p>Eight visual frames plus the icon, rendered at3×; seven actual phone screens checked at402×874 and375×667. Zero scan failures at both sizes. Two full-set reviews:45→48/60, all12 criteria at4 in the final round. See <code>CRITIQUE-A2.md</code>. Camera and input studies support reduced motion.</p><p>Latest sheet: <code>shots/{folder}/sheet.png</code><br>Editable concepts: <code>mockup.html</code><br>Motion gallery: <code>presentation-a2.html</code><br>Data and geometry sources: <code>REFERENCES.md</code></p><p>Not included yet: production SwiftUI/Android build, subscription/account flow, real broadcasts or a licensed live feed. The camera film does not animate the cars themselves.</p></details></main>'''
navjs='''const presentation=document.querySelector('main');const screenInfo='''+json.dumps([[p[1],p[2],p[3]]for p in P],separators=(',',':'))+''';const screenImages=[...document.querySelectorAll('.screen-grid img')];function mode(k){presentation.dataset.mode=k;document.querySelectorAll('.modebar button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mode===k)));window.scrollTo(0,0)}document.querySelectorAll('.modebar button').forEach(b=>b.addEventListener('click',()=>mode(b.dataset.mode)));document.querySelectorAll('[data-screen]').forEach(b=>b.addEventListener('click',()=>{const i=+b.dataset.screen,c=screenInfo[i],im=screenImages[i];mode('focus');document.querySelector('#focus-image').src=im.src;document.querySelector('#focus-image').alt=im.alt;document.querySelector('#focus-index').textContent='Screen '+String(i+1).padStart(2,'0');document.querySelector('#focus-title').textContent=c[0];document.querySelector('#focus-description').textContent=c[1];document.querySelector('#focus-note').textContent=c[2]}));document.querySelector('.back-all').addEventListener('click',()=>mode('screens'));'''
js=navjs+data+(ROOT/'assets/a2/motion-ui.js').read_text()
page='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Vantage A — the expanded race instrument</title><style>'+css+'</style></head><body>'+body+'<script>'+js+'</script></body></html>'
for a,b in [('Original3D','Original 3D'),('actual3D','actual 3D'),('reconstructed3D','reconstructed 3D'),('all22','all 22'),('All22','All 22'),('lap30','lap 30'),('at3×','at 3×'),('at402','at 402'),('and375','and 375'),('A30-frame','A 30-frame'),('45→48/60','45 → 48/60'),('all12','all 12'),('at4 in','at 4 in')]:page=page.replace(a,b)
for token,fallback in [('foreground','#162923'),('muted-foreground','#52675e'),('background','#ffffff'),('border','#c9d3ce'),('secondary','#e7ece9'),('ring','#688db5'),('radius','12px')]:page=page.replace('var(--'+token+')','var(--'+token+','+fallback+')')
(ROOT/'presentation-a2.html').write_text(page)
print('Built presentation-a2.html:',len(page),'bytes; images local for T3 inlining.')
